/* The graph is derived from the course's actual prerequisites, never a second syllabus. */
let treeTopic='all',treeSelected=null,treeExpanded=false;
function learningTreeLayout(skills){const byId=new Map(skills.map(s=>[s.id,s])),depths=new Map(),visiting=new Set();function depth(id){if(depths.has(id))return depths.get(id);if(visiting.has(id))throw Error('技能先修關係不可循環');const s=byId.get(id);if(!s)throw Error('找不到先修技能 '+id);visiting.add(id);const n=s.requires.length?1+Math.max(...s.requires.map(depth)):0;visiting.delete(id);depths.set(id,n);return n}const rows=[];skills.forEach(s=>(rows[depth(s.id)]??=[]).push(s));const width=Math.max(...rows.map(r=>r.length))*138+40,positions=new Map();rows.forEach((r,i)=>{r.sort((a,b)=>a.branch-b.branch||skills.indexOf(a)-skills.indexOf(b));r.forEach((s,j)=>positions.set(s.id,{x:(width-r.length*138)/2+j*138+6,y:62+i*146}))});return{width,height:rows.length*146+82,positions,depths}}
function renderLearningTree(){const grid=document.getElementById('topic-grid');grid.classList.add('learning-tree');grid.removeAttribute('role');grid.removeAttribute('aria-label');grid.replaceChildren();const make=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};const tools=make('div',undefined,'tree-toolbar'),label=make('label','聚焦主題 '),select=make('select');select.setAttribute('aria-label','聚焦技能樹主題');select.append(new Option('全部學習路線','all'));SKILL_TOPICS.forEach(t=>select.append(new Option(t.name,t.id)));select.value=treeTopic;select.onchange=()=>{treeTopic=select.value;treeSelected=null;renderLearningTree()};label.append(select);const expand=make('button',treeExpanded?'收合為捲動視窗':'展開完整技能樹');expand.type='button';expand.setAttribute('aria-expanded',String(treeExpanded));expand.onclick=()=>{treeExpanded=!treeExpanded;renderLearningTree()};tools.append(label,expand);grid.append(tools);const legend=make('div',undefined,'tree-legend');for(const [cls,text]of [['new','○ 尚未開始'],['learning','◐ 正在學習'],['practiced','● 已練習（自記）'],['ready','↗ 建議下一步']])legend.append(make('span',text,cls));grid.append(legend);
const view=make('div',undefined,'tree-viewport'+(treeExpanded?' expanded':''));view.tabIndex=0;view.setAttribute('role','region');view.setAttribute('aria-label','技能學習樹，可上下與左右捲動；按 Tab 選擇技能');const layout=learningTreeLayout(SKILLS),canvas=make('div',undefined,'tree-canvas');canvas.style.width=layout.width+'px';canvas.style.height=layout.height+'px';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',`0 0 ${layout.width} ${layout.height}`);svg.setAttribute('aria-hidden','true');svg.classList.add('tree-lines');canvas.append(svg);const stage=make('span','從這裡開始 ↓','tree-start');stage.style.left=layout.width/2+'px';canvas.append(stage);
const wanted=treeTopic==='all'?new Set(SKILLS.map(s=>s.id)):new Set(SKILL_TOPICS.find(t=>t.id===treeTopic).skills),ancestors=new Set();function collect(id,set){if(set.has(id))return;set.add(id);byId.get(id).requires.forEach(p=>collect(p,set))}wanted.forEach(id=>collect(id,ancestors));const edges=[];
for(const s of SKILLS){const pos=layout.positions.get(s.id);for(const parent of s.requires){const p=layout.positions.get(parent),path=document.createElementNS('http://www.w3.org/2000/svg','path');const x1=p.x+63,y1=p.y+102,x2=pos.x+63,y2=pos.y;path.setAttribute('d',`M ${x1} ${y1} C ${x1} ${y1+(y2-y1)/2}, ${x2} ${y1+(y2-y1)/2}, ${x2} ${y2}`);path.setAttribute('class','tree-edge'+(statusOf(parent)==='practiced'?' practiced':'')+(!ancestors.has(s.id)?' muted':''));svg.append(path);edges.push({path,parent,child:s.id})}}
const buttons=new Map();for(const s of SKILLS){const pos=layout.positions.get(s.id),b=make('button',undefined,'tree-skill'+(!ancestors.has(s.id)?' muted':'')+(wanted.has(s.id)&&treeTopic!=='all'?' topic-match':''));b.type='button';b.id='tree-node-'+s.id;b.dataset.status=statusOf(s.id);b.dataset.level=s.level;b.style.left=pos.x+'px';b.style.top=pos.y+'px';b.style.setProperty('--tree-color',colors[s.level]);const ready=statusOf(s.id)!=='practiced'&&s.requires.every(id=>statusOf(id)==='practiced');if(ready)b.classList.add('ready');const meta=make('span',s.level+(ready?' · 下一步':''),'tree-node-meta'),icon=skillIdentityIcon(s.id),title=make('b',s.name),state=make('span',statusLabel[statusOf(s.id)],'tree-node-state');b.append(meta,icon,title,state);b.setAttribute('aria-label',s.level+' '+s.name+'，'+statusLabel[statusOf(s.id)]+'。'+(s.requires.length?'建議先修：'+s.requires.map(id=>byId.get(id).name).join('、'):'學習起點')+'。開啟技能詳情');b.onclick=()=>{treeSelected=s.id;highlight(s.id);showSkill(s.id)};b.onmouseenter=()=>highlight(s.id);b.onfocus=()=>highlight(s.id);b.onmouseleave=()=>highlight(treeSelected);buttons.set(s.id,b);canvas.append(b)}
function highlight(id){const route=new Set();if(id)collect(id,route);edges.forEach(e=>{e.path.classList.toggle('highlight',!!id&&route.has(e.child)&&route.has(e.parent));e.path.classList.toggle('faded',!!id&&!(route.has(e.child)&&route.has(e.parent)))});buttons.forEach((b,key)=>{b.classList.toggle('on-route',!!id&&route.has(key));b.classList.toggle('selected',key===id)})}if(treeSelected)highlight(treeSelected);view.append(canvas);grid.append(view);grid.append(make('p','連線由上往下代表建議先修順序；點選技能查看練習重點。專項依各自先修能力分支，自記練習不等同教練認證。','tree-footnote'));if(treeTopic!=='all'){const first=SKILLS.find(s=>wanted.has(s.id));if(first){const p=layout.positions.get(first.id);view.scrollTop=Math.max(0,p.y-80);view.scrollLeft=Math.max(0,p.x-view.clientWidth/2+63)}}else view.scrollLeft=Math.max(0,(layout.width-view.clientWidth)/2)}
